/**
 * 弹窗管理
 */
cc.Class({
    extends: cc.Component,

    properties: {

    },

    // LIFE-CYCLE CALLBACKS:

    onLoad () {

    },

    start () {

    },

    showWin(){
        this.node.active = true
        let popBg = cc.find("popup",this.node)
        popBg.opacity = 0
        cc.tween(popBg).to(0.3,{opacity:255}).start()
        let guochang = cc.find("guochang",this.node)
        guochang.active = false
    },

    showWinEx(){
        this.node.active = true
        let popBg = cc.find("popup",this.node)
        popBg.opacity = 0
        let guochang = cc.find("guochang",this.node)
        guochang.active = true
    },

    hideWin(callBack){
        let popBg = cc.find("popup",this.node)
        cc.tween(popBg).to(0.3,{opacity:0}).call(()=>{
            if(callBack){
                callBack()
            }
            this.node.active = false
        }).start()
    },

    hideWinEx(callBack){
        let guochang = cc.find("guochang",this.node)
        guochang.active = false
        if(callBack){
            callBack()
        }
        this.node.active = false
    },

    awaitTime(time){
        return new Promise((sucess, failed)=>{
            this.scheduleOnce(()=>{
                sucess()
            },time);
        });
    },

    showFreeGameTimes(num){
        return new Promise(async (sucess, failed)=>{
            Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.fgbegin)
            this.showWinEx()
            let show_popup = cc.find("show_freeGameTimes",this.node)
            show_popup.active = true;
            let freeTimes = cc.find("times",show_popup)
            freeTimes.active = true
            show_popup.scale = 0
            cc.tween(show_popup).to(0.5,{scale:1},{easing:"backOut"}).start()
            await this.awaitTime(2.5)

            cc.tween(show_popup).to(0.5,{scale:0},{easing:"backIn"}).start()
            await this.awaitTime(0.5)
            this.hideWinEx(()=>{
                sucess()
            })
        });
    },

    //显示免费游戏赢金币
    showFreeGameWinCoin(num){
        return new Promise(async (sucess, failed)=>{
            Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.fgend)
            this.showWinEx()
            let show_popup = cc.find("show_freeGame_winCoin",this.node)
            show_popup.active = true;
            let coin = cc.find("coin",show_popup)
            let collectBtn = cc.find("collectBtn",show_popup)
            show_popup.scale = 0
            cc.tween(show_popup).to(0.5,{scale:1},{easing:"backOut"}).start()
            this._startAddCoin = true
            Global.doRoallNumEff(coin,Math.floor(num*0.1),num,2.5,()=>{
                this._startAddCoin = false
            },null,0,true);
            collectBtn.getComponent(cc.Button).interactable = true
            collectBtn.off("click");
            let func = async ()=>{
                collectBtn.getComponent(cc.Button).interactable = false
                if(this._startAddCoin){
                    this._startAddCoin = false
                    coin.stopAllActions()
                    let winCoinLabel = coin.getComponent(cc.Label)
                    winCoinLabel.string = Global.FormatNumToComma(num)
                }
                await this.awaitTime(0.2)
                cc.tween(show_popup).to(0.5,{scale:0},{easing:"backIn"}).start()
                await this.awaitTime(0.5)
                this.hideWinEx(()=>{
                    sucess()
                })
            }
            cc.vv.gameData.checkAutoPlay(collectBtn, func)
            collectBtn.on("click", async ()=>{
                collectBtn.stopAllActions();
                await func();
            });  
        });
    },

    showFreeGameWinFree(num){
        return new Promise(async (sucess, failed)=>{
            Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.fgtrans)
            this.showWin()
            let show_popup = cc.find("show_freeGame_winfree",this.node)
            show_popup.active = true;
            if(num === 5){
                let freeTimes5 = cc.find("times5",show_popup)
                freeTimes5.active = true
                let freeTimes8 = cc.find("times8",show_popup)
                freeTimes8.active = false
            }else{
                let freeTimes8 = cc.find("times8",show_popup)
                freeTimes8.active = true
                let freeTimes5 = cc.find("times5",show_popup)
                freeTimes5.active = false
            }
            show_popup.scale = 0
            cc.tween(show_popup).to(0.5,{scale:1},{easing:"backOut"}).start()
            await this.awaitTime(2.5)
            cc.tween(show_popup).to(0.5,{scale:0},{easing:"backIn"}).start()
            await this.awaitTime(0.5)
            this.hideWin(()=>{
                sucess()
            })
        });
    },

    showJackPotWinCoin(num){
        return new Promise(async (sucess, failed)=>{
            Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.JPwin)
            this.showWin()
            let show_popup = cc.find("show_win_jackpot",this.node)
            show_popup.active = true;
            let coin = cc.find("coin",show_popup)
            let collectBtn = cc.find("collectBtn",show_popup)
            show_popup.scale = 0
            cc.tween(show_popup).to(0.5,{scale:1},{easing:"backOut"}).start()
            this._startAddCoin = true
            Global.doRoallNumEff(coin,Math.floor(num*0.1),num,2.5,()=>{
                this._startAddCoin = false
            },null,0,true);
            collectBtn.getComponent(cc.Button).interactable = true
            collectBtn.off("click");
            let func = async ()=>{
                collectBtn.getComponent(cc.Button).interactable = false
                if(this._startAddCoin){
                    this._startAddCoin = false
                    coin.stopAllActions()
                    let winCoinLabel = coin.getComponent(cc.Label)
                    winCoinLabel.string = Global.FormatNumToComma(num)
                }
                await this.awaitTime(0.2)
                cc.tween(show_popup).to(0.5,{scale:0},{easing:"backIn"}).start()
                await this.awaitTime(0.5)
                this.hideWin(()=>{
                    sucess()
                })
            }
            cc.vv.gameData.checkAutoPlay(collectBtn, func);
            collectBtn.on("click", async ()=>{
                collectBtn.stopAllActions();
                await func();
            });
        });
    },
    // update (dt) {},
});
