/**
 * 游戏自己的gamedata
 */
cc.Class({
    extends: require("LMSlots_GameData_Base"),

    properties: {
        _collectNode:null,
        _popWin:null,
        _qiePing:null,
        _slotsArr:[],
        _slotsIndex:0,
        _wildTrans:null,
        _manage:null,
    },

    getCollectNode:function(){
        return this._collectNode
    },
    setCollectNode(script){
        this._collectNode = script
    },

    getPopWinManage(){
        return this._popWin
    },
    setPopWinManage(script){
        this._popWin = script
    },

    getQiePing(){
        return this._qiePing
    },
    setQiePing(script){
        this._qiePing = script
    },  

    addSlots(cmp){
        this._slotsArr.push(cmp);
    },

    setSlotsIndex(index){
        this._slotsIndex = index
    },

    //获得游戏的slots脚本
    GetSlotsScript:function(){
        return this._slotsArr[this._slotsIndex]
    },

    GetSlotsScriptById(idx){
        return this._slotsArr[idx]
    },

    getWildTransition(){
        return this._wildTrans
    },
    setWildTransition(script){
        this._wildTrans = script
    },

    showSlot(){
        for (let i = 0; i < this._slotsArr.length; i++) {
            const slot = this._slotsArr[i];
            if(i == this._slotsIndex){
                slot.show()
            }else{
                slot.hide()
            }
        }
    },

    getManage(){
        return this._manage
    },
    setManage(script){
        this._manage = script
    },

    // update (dt) {},
});
