cc.Class({
    extends: cc.Component,

    properties: {
        _transitionMap:null,
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad () {
        this._transitionMap = {}
        this._transitionMap["L_Blue1x3"] = cc.find("L_Blue1x3",this.node)
        this._transitionMap["L_Blue1x4"] = cc.find("L_Blue1x4",this.node)
        this._transitionMap["L_Blue1x9"] = cc.find("L_Blue1x9",this.node)
        this._transitionMap["L_Red3x3"] = cc.find("L_Red3x3",this.node)
        this._transitionMap["L_Red3x9"] = cc.find("L_Red3x9",this.node)
        this._transitionMap["L_Red3x4x5"] = cc.find("L_Red3x4x5",this.node)
        this._transitionMap["R_Blue1x3"] = cc.find("R_Blue1x3",this.node)
        this._transitionMap["R_Blue1x4"] = cc.find("R_Blue1x4",this.node)
        this._transitionMap["R_Blue1x9"] = cc.find("R_Blue1x9",this.node)
        this._transitionMap["R_Red3x3"] = cc.find("R_Red3x3",this.node)
        this._transitionMap["R_Red3x9"] = cc.find("R_Red3x9",this.node)
        this._transitionMap["R_Red3x4x5"] = cc.find("R_Red3x4x5",this.node)
        this._transitionMap["Red5x3"] = cc.find("Red5x3",this.node)
        this._transitionMap["Red5x5x5"] = cc.find("Red5x5x5",this.node)
        this._transitionMap["Red5x9"] = cc.find("Red5x9",this.node)
    },

    onDestroy(){

    },

    start () {

    },

    awaitTime(time){
        return new Promise((sucess, failed)=>{
            this.scheduleOnce(()=>{
                sucess()
            },time);
        });
    },

    showTransition(type){
        let transitionNode = this._transitionMap[type]
        if(transitionNode){
            transitionNode.active = true
            let transitionNodeSp = transitionNode.getComponent(sp.Skeleton)
            switch (type) {
                case "L_Blue1x3":
                case "L_Blue1x4":
                case "L_Blue1x9":
                case "R_Blue1x3":
                case "R_Blue1x4":
                case "R_Blue1x9":
                    Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.wildreel1)
                    break
                case "L_Red3x3":
                case "L_Red3x9":
                case "L_Red3x4x5":
                case "R_Red3x3":
                case "R_Red3x9":
                case "R_Red3x4x5":
                    Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.wildreel3)
                    break
                case "Red5x3":
                case "Red5x5x5":
                case "Red5x9":
                    Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.AllOfAKind)
                    cc.vv.gameData.getManage().showAllOfAKindi()
                    break
            }
            transitionNodeSp.setCompleteListener(()=>{
                transitionNode.active = false
            })
        }
    },

    showBonus(bonusInfo,callBack){
        return new Promise(async (success,failed)=>{
            Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.Voice_PowerZone)
            await this.awaitTime(0.2)
            let col1 = bonusInfo.wildCols.includes(1)
            let col2 = bonusInfo.wildCols.includes(2)
            let col3 = bonusInfo.wildCols.includes(3)
            let col4 = bonusInfo.wildCols.includes(4)
            let col5 = bonusInfo.wildCols.includes(5)
            let isFreeGame = cc.vv.gameData.getManage()._isInFree
            let isDouble = cc.vv.gameData.getCollectNode().isDoubleGame()
            if(isFreeGame){
                if(col1 && col2 && col3 && col4 && col5){
                    this.showTransition("Red5x9")
                }else if(col1 && col2 && col3 && col4){
                    this.showTransition("L_Red3x9")
                    this.showTransition("R_Blue1x9")
                }else if(col2 && col3 && col4 && col5){
                    this.showTransition("L_Blue1x9")
                    this.showTransition("R_Red3x9")
                }else if(col1 && col2 && col3){
                    this.showTransition("L_Red3x9")
                }else if(col3 && col4 && col5){
                    this.showTransition("R_Red3x9")
                }else if(col2 && col4){
                    this.showTransition("R_Blue1x9")
                    this.showTransition("L_Blue1x9")
                }else if(col2){
                    this.showTransition("L_Blue1x9")
                }else if(col4){
                    this.showTransition("R_Blue1x9")
                }
            }else{
                if(isDouble){
                    if(col1 && col2 && col3 && col4 && col5){
                        this.showTransition("Red5x5x5")
                    }else if(col1 && col2 && col3 && col4){
                        this.showTransition("L_Red3x4x5")
                        this.showTransition("R_Blue1x4")
                    }else if(col2 && col3 && col4 && col5){
                        this.showTransition("L_Blue1x4")
                        this.showTransition("R_Red3x4x5")
                    }else if(col1 && col2 && col3){
                        this.showTransition("L_Red3x4x5")
                    }else if(col3 && col4 && col5){
                        this.showTransition("R_Red3x4x5")
                    }else if(col2 && col4){
                        this.showTransition("R_Blue1x4")
                        this.showTransition("L_Blue1x4")
                    }else if(col2){
                        this.showTransition("L_Blue1x4")
                    }else if(col4){
                        this.showTransition("R_Blue1x4")
                    }
                }else{
                    if(col1 && col2 && col3 && col4 && col5){
                        this.showTransition("Red5x3")
                    }else if(col1 && col2 && col3 && col4){
                        this.showTransition("L_Red3x3")
                        this.showTransition("R_Blue1x3")
                    }else if(col2 && col3 && col4 && col5){
                        this.showTransition("L_Blue1x3")
                        this.showTransition("R_Red3x3")
                    }else if(col1 && col2 && col3){
                        this.showTransition("L_Red3x3")
                    }else if(col3 && col4 && col5){
                        this.showTransition("R_Red3x3")
                    }else if(col2 && col4){
                        this.showTransition("R_Blue1x3")
                        this.showTransition("L_Blue1x3")
                    }else if(col2){
                        this.showTransition("L_Blue1x3")
                    }else if(col4){
                        this.showTransition("R_Blue1x3")
                    }
                }
            }
            await this.awaitTime(0.5)
            if(callBack){
                callBack()
            }
            await this.awaitTime(2)
            success()
        })
    },
    // update (dt) {},
});
