
cc.Class({
    extends: cc.Component,

    properties: {
        qiepin:{
            default:null,
            type:cc.Node
        },
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad () {

    },

    onDestroy(){

    },

    start () {

    },

    awaitTime(time){
        return new Promise((sucess, failed)=>{
            this.scheduleOnce(()=>{
                sucess()
            },time);
        });
    },

    showQP(callBack){
        return new Promise(async (sucess, failed)=>{
            // Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.transition_free)
            this.qiepin.active = true
            let show_popupSp = this.qiepin.getComponent(sp.Skeleton)
            show_popupSp.setAnimation(0,"FG_guochang_intro",false)
            show_popupSp.setCompleteListener(()=>{
                this.qiepin.active = false
                sucess()
                show_popupSp.setCompleteListener(null)
            })
            await this.awaitTime(0.5)
            if(callBack){
                callBack()
            }
        });
    },

    showDaJiangYuGao(){
        return new Promise(async (sucess, failed)=>{
            Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.bigAward)
            this.qiepin.active = true
            let show_popupSp = this.qiepin.getComponent(sp.Skeleton)
            show_popupSp.setAnimation(0,"dajiangyugao",false)
            show_popupSp.setCompleteListener(()=>{
                this.qiepin.active = false
                sucess()
                show_popupSp.setCompleteListener(null)
            })
        });
    },

    // update (dt) {},
});
