cc.Class({
    extends: require("LMSlots_PrizePool_Base"),

    properties: {

    },

    start () {
        this._super()
        this.scheduleOnce(()=>{
            if(this.node.y + this.node.height/2 > cc.winSize.height / 2 - 74){
                let length = (this.node.y + this.node.height/2) - (cc.winSize.height / 2 - 74)
                this.node.y -= length
            }
        },0);
    },
    
    //各个节点上的解锁/锁定表现
    ShowNodeLockByNode:function(node,bLock,unLockBet,poolType,bInit){

    },

    setPrizePoxY(bFree){
        let node = cc.find("prizePool_Grand", this.node)
        if (bFree){
            node.y = 45;
        } else {
            node.y = 0
        }
    }

    // update (dt) {},
});
